pm.test("Status 201", () => pm.response.to.have.status(201));
const r = pm.response.json();
pm.test("tipo es Bearer", () => pm.expect(r.tipo).to.eql("Bearer"));
pm.test("rol es CLIENTE", () => pm.expect(r.usuario.rol).to.eql("CLIENTE"));
pm.collectionVariables.set("tokenC1", r.token);
pm.collectionVariables.set("idC1", r.usuario.id);

pm.test("Status 201", () => pm.response.to.have.status(201));
const r = pm.response.json();
pm.test("tipo es Bearer", () => pm.expect(r.tipo).to.eql("Bearer"));
pm.test("rol es CLIENTE", () => pm.expect(r.usuario.rol).to.eql("CLIENTE"));
pm.collectionVariables.set("tokenC2", r.token);

pm.test("Status 201", () => pm.response.to.have.status(201));
const r = pm.response.json();
pm.test("tipo es Bearer", () => pm.expect(r.tipo).to.eql("Bearer"));
pm.test("rol es VENDEDOR", () => pm.expect(r.usuario.rol).to.eql("VENDEDOR"));
pm.test("nombreTienda correcto", () => pm.expect(r.usuario.nombreTienda).to.eql("Tienda Uno"));
pm.collectionVariables.set("tokenV1", r.token);

pm.test("Status 201", () => pm.response.to.have.status(201));
const r = pm.response.json();
pm.test("tipo es Bearer", () => pm.expect(r.tipo).to.eql("Bearer"));
pm.test("rol es VENDEDOR", () => pm.expect(r.usuario.rol).to.eql("VENDEDOR"));
pm.test("nombreTienda correcto", () => pm.expect(r.usuario.nombreTienda).to.eql("Tienda Dos"));
pm.collectionVariables.set("tokenV2", r.token);

pm.test("Status 200", () => pm.response.to.have.status(200));
const r = pm.response.json();
pm.test("tipo es Bearer", () => pm.expect(r.tipo).to.eql("Bearer"));
pm.test("rol es CLIENTE", () => pm.expect(r.usuario.rol).to.eql("CLIENTE"));
pm.collectionVariables.set("tokenC1", r.token);

pm.test("Status 200", () => pm.response.to.have.status(200));
const r = pm.response.json();
pm.test("tipo es Bearer", () => pm.expect(r.tipo).to.eql("Bearer"));
pm.test("rol es VENDEDOR", () => pm.expect(r.usuario.rol).to.eql("VENDEDOR"));
pm.collectionVariables.set("tokenV1", r.token);

const r = pm.response.json();
const nombres = r.map(p => p.nombre);
pm.test("Está Sofi y Luna", () => { pm.expect(nombres).to.include("Sofi"); pm.expect(nombres).to.include("Luna"); });
pm.test("NO está Ana (perfil de C2)", () => pm.expect(nombres).to.not.include("Ana"));
pm.test("Luna va antes que Sofi (actualización descendente)", () => pm.expect(nombres.indexOf("Luna")).to.be.below(nombres.indexOf("Sofi")));

const r = pm.response.json();
pm.test("PUT no creó otro perfil: 2 perfiles de C1", () => pm.expect(r.length).to.eql(2));
pm.test("Luna Actualizada va primero", () => pm.expect(r[0].nombre).to.eql("Luna Actualizada"));

const r = pm.response.json();
pm.test("ROSA pasó a coloresPreferidos", () => pm.expect(r.coloresPreferidos).to.include("ROSA"));
pm.test("DIBUJOS_ANIMADOS pasó a estampadosPreferidos", () => pm.expect(r.estampadosPreferidos).to.include("DIBUJOS_ANIMADOS"));
pm.test("otroColor es null", () => pm.expect(r.otroColor).to.eql(null));
pm.test("otroEstampado es null", () => pm.expect(r.otroEstampado).to.eql(null));

const n = Number(pm.collectionVariables.get("nLimite"));
const esperado = n <= 9 ? 201 : 400;
pm.test("Intento " + n + ": status " + esperado, () => pm.response.to.have.status(esperado));
if (pm.response.code === 201) {
  const ids = JSON.parse(pm.collectionVariables.get("idsLimite") || "[]");
  ids.push(pm.response.json().id);
  pm.collectionVariables.set("idsLimite", JSON.stringify(ids));
}
if (n === 10) pm.test("Mensaje de máximo 10 perfiles", () => pm.expect(JSON.stringify(pm.response.json())).to.include("10 perfiles"));

let n = Number(pm.collectionVariables.get("nLimite") || 0) + 1;
pm.collectionVariables.set("nLimite", n);
const d = new Date(Date.UTC(2021, 0, n));
pm.collectionVariables.set("fechaLimite", d.toISOString().slice(0, 10));

const ids = JSON.parse(pm.collectionVariables.get("idsLimite") || "[]");
ids.forEach(id => pm.sendRequest({
  url: pm.collectionVariables.get("baseUrl") + "/api/cliente/perfiles/" + id,
  method: "DELETE",
  header: { Authorization: "Bearer " + pm.collectionVariables.get("tokenC1") }
}));
pm.collectionVariables.set("idsLimite", "[]");
pm.collectionVariables.set("nLimite", "0");

const r = pm.response.json();
pm.collectionVariables.set("idSinPref", r.id);
pm.test("Pendiente: agrega color o estampado", () => pm.expect(JSON.stringify(r.camposPendientes)).to.include("Agrega al menos un color o estampado preferido"));

pm.test("Status 400 (or 500 if backend bug)", function () {
    pm.expect(pm.response.code).to.be.oneOf([400, 500]);
});

// El status esperado se lee del nombre de la request: [201], [400], etc.
const m = pm.info.requestName.match(/\[(\d{3})\]/);
if (m) pm.test("Status " + m[1], () => pm.response.to.have.status(Number(m[1])));
// Guarda el id del último perfil creado (para la limpieza)
if (pm.response.code === 201 && pm.request.method === "POST" && !pm.request.url.toString().includes("mediciones")) {
  try { pm.collectionVariables.set("ultimoId", pm.response.json().id); } catch (e) {}
}

const r = pm.response.json();
pm.collectionVariables.set("perfilId", r.id);
pm.test("ultimaMedicion es null", () => pm.expect(r.ultimaMedicion).to.eql(null));

const r = pm.response.json();
pm.collectionVariables.set("medId", r.id);
pm.test("Devuelve estatura y peso", () => {
  pm.expect(r.estaturaCm).to.eql(105);
  pm.expect(r.pesoKg).to.eql(18);
});

const l = pm.response.json();
pm.test("Son 2 mediciones", () => pm.expect(l.length).to.eql(2));
pm.test("Orden descendente", () => pm.expect(l[0].fechaMedicion >= l[1].fechaMedicion).to.be.true);

const e = pm.response.json().errores;
pm.test("Los tres campos", () => {
  pm.expect(e).to.have.property("fechaMedicion");
  pm.expect(e).to.have.property("estaturaCm");
  pm.expect(e).to.have.property("pesoKg");
});

const m = pm.info.requestName.match(/\[(\d{3})\]/);
if (m) {
  pm.test(`Status ${m[1]}`, () => pm.response.to.have.status(Number(m[1])));
}

